// Retail 0x00729700 (792 bytes): W3DTerrainBackground::setFlipRecursive(Int, Int, Int).
// Identity: setFlip 0x00729F00 and rva0072E150/rva0072DC30 call it through
// ILT 0x0001B5F9 with (0, 0, m_width), and it recurses on itself through the
// same stub three times plus a tail-recursive fourth quadrant, the ZH
// setFlipRecursive shape. BFME adds a minimum-width stop (this+0x78), a
// cliff/feature cell test (map +0x94 indexed through the draw origin
// +0x120E0/+0x120E4), a flip-bit comparison against the corner cell, and
// isEdgeAligned gates on each corner.

typedef bool Bool;
typedef int Int;
typedef unsigned short UnsignedShort;
typedef unsigned char Byte;

// upstream layout: inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngineDevice/Include/W3DDevice/GameClient/WorldHeightMap.h
// BFME offsets witnessed by the retail body and WorldHeightMap_dtor.cpp.
class WorldHeightMap
{
public:
	Int getXExtent(void) { return m_width; }
	Int getYExtent(void) { return m_height; }
	UnsignedShort getHeight(Int xIndex, Int yIndex)
	{
		Int ndx = (yIndex*m_width) + xIndex;
		if ((ndx >= 0) && (ndx < m_dataSize) && m_data)
			return m_data[ndx];
		return 0;
	}
	Bool getCellFeature(Int xIndex, Int yIndex)
	{
		Int ndx = ((yIndex + m_drawOriginY)*m_width) + m_drawOriginX + xIndex;
		if ((ndx >= 0) && (ndx < m_dataSize))
			return m_cellFeatures[ndx] != 0;
		return false;
	}
	Bool getFlipBit(Int xIndex, Int yIndex)
	{
		if (xIndex < 0 || yIndex < 0 || yIndex >= m_height || xIndex >= m_width)
			return false;
		const Int index = m_flipStride * yIndex + (xIndex >> 3);
		if ((unsigned)index >= (unsigned)(m_flipEnd - m_flipBegin))
			return false;
		return (m_flipBegin[index] & (1 << (xIndex & 7))) != 0;
	}

private:
	Byte m_pad00[0x08];
	Int m_width;                    // +0x08
	Int m_height;                   // +0x0C
	Byte m_pad10[0x10];
	Int m_dataSize;                 // +0x20
	UnsignedShort *m_data;          // +0x24
	Byte m_pad28[0x0C];
	Int m_flipStride;               // +0x34
	Byte m_pad38[0x18];
	Byte *m_flipBegin;              // +0x50
	Byte *m_flipEnd;                // +0x54
	Byte m_pad58[0x3C];
	Int *m_cellFeatures;            // +0x94
	Byte m_pad98[0x120E0 - 0x98];
	Int m_drawOriginX;              // +0x120E0
	Int m_drawOriginY;              // +0x120E4
};

// Retail 0x00729370, reached through ILT 0x0004ABB0 with ecx = m_map.
class Rva00729370BitPlane
{
public:
	Bool test(Int x, Int y) const;
};

// Retail 0x00749830, reached through ILT 0x0003F7C4 with ecx = m_map.
class BfmeMaskAX
{
public:
	void bfmeMarkAX(Int x, Int y, unsigned char value);
};

// upstream layout: inputs/reference/CnC_Generals_Zero_Hour/GeneralsMD/Code/GameEngineDevice/Include/W3DDevice/GameClient/W3DTerrainBackground.h
class W3DTerrainBackground
{
public:
	Bool isEdgeAligned(Int x, Int y, Int width);

protected:
	void setFlipRecursive(Int xOffset, Int yOffset, Int width);

private:
	Byte m_pad00[0x40];
	Int m_xOrigin;                  // +0x40
	Int m_yOrigin;                  // +0x44
	Int m_width;                    // +0x48
	WorldHeightMap *m_map;          // +0x4C
	Byte m_pad50[0x28];
	Int m_78;                       // +0x78 minimum tile step
};

void W3DTerrainBackground::setFlipRecursive(Int xOffset, Int yOffset, Int width)
{
	Int limitX = m_map->getXExtent()-1;
	Int limitY = m_map->getYExtent()-1;
	Int i, j;
	Bool match = true;
	Int minX = m_xOrigin+xOffset;
	Int minY = m_yOrigin+yOffset;
	Int cornerHeight = m_map->getHeight(minX, minY);
	WorldHeightMap *map = m_map;
	Bool cornerFlip = ((Rva00729370BitPlane *)map)->test(minX, minY);

	for (i=0; i<=width; i+=m_78) {
		for (j=0; j<=width; j+=m_78) {
			Int k = minX+i;
			k = k<limitX?k:limitX;
			Int l = minY+j;
			l = l<limitY?l:limitY;
			if (cornerHeight!=map->getHeight(k, l)) {
				match = false;
				break;
			}
			if (map->getCellFeature(k, l)) {
				match = false;
				break;
			}
			Bool flip = (i<width && j<width) ? map->getFlipBit(k, l) : false;
			if (flip != cornerFlip) {
				match = false;
				break;
			}
		}
	}
	if (width==m_78) {
		match = true;
	}

	if (match) {
		Int maxX = minX+width;
		maxX = maxX<limitX?maxX:limitX;
		Int maxY = minY+width;
		maxY = maxY<limitY?maxY:limitY;
		Int yOrigin = m_yOrigin;
		Bool edge3 = isEdgeAligned(minX-m_xOrigin, maxY-yOrigin, width);
		Bool edge2 = isEdgeAligned(maxX-m_xOrigin, maxY-yOrigin, width);
		Bool edge1 = isEdgeAligned(maxX-m_xOrigin, minY-yOrigin, width);
		Bool edge0 = isEdgeAligned(minX-m_xOrigin, minY-yOrigin, width);
		if (edge0)
			((BfmeMaskAX *)m_map)->bfmeMarkAX(minX, minY, true);
		if (edge1)
			((BfmeMaskAX *)m_map)->bfmeMarkAX(maxX, minY, true);
		if (edge2)
			((BfmeMaskAX *)m_map)->bfmeMarkAX(maxX, maxY, true);
		if (edge3)
			((BfmeMaskAX *)m_map)->bfmeMarkAX(minX, maxY, true);
		return;
	}
	Int halfWidth = width/2;

	setFlipRecursive(xOffset, yOffset, halfWidth);
	setFlipRecursive(xOffset, yOffset+halfWidth, halfWidth);
	setFlipRecursive(xOffset+halfWidth, yOffset, halfWidth);
	setFlipRecursive(xOffset+halfWidth, yOffset+halfWidth, halfWidth);
}
